#!/usr/bin/env Rscript
# Reconcile gllvmTMB's public capability ledger (docs/design/capability-status.md,
# generated by dev/gapclose/build-capability-status.R from the validation-debt
# register) against GLLVM.jl's own docs/design/capability-status.md, at a named
# git ref. Mirrors DRM.jl's tools/parity_ledger.py precedent: matched rows,
# an "AHEAD OF gllvmTMB, ACCOUNTED FOR IN WRITING" section for every
# Julia-only row (port / accounted / divergence disposition), the symmetric
# "AHEAD OF GLLVM.jl" R-only list, and a closing CLOSURE: PASS / FAIL line.
#
# Usage:
#   Rscript tools/parity_ledger.R
#   Rscript tools/parity_ledger.R --ref origin/main
#   Rscript tools/parity_ledger.R --julia-repo "/path/to/GLLVM.jl" --ref origin/main
#   Rscript tools/parity_ledger.R --julia /path/to/a/capability-status.md   # read a file directly
#   Rscript tools/parity_ledger.R --check-names                            # near-miss / grouping-level assertions
#
# Julia source resolution (no --julia given): `git -C <julia-repo> show
# <ref>:docs/design/capability-status.md`, where <julia-repo> defaults to
# /Users/z3437171/Dropbox/Github Local/GLLVM.jl and <ref> defaults to
# origin/main; if that git call fails (repo absent, ref absent, git error),
# fall back to the scratchpad copy so the tool still runs.

args <- commandArgs(trailingOnly = TRUE)
get_flag <- function(flag, default = NULL) {
  i <- which(args == flag)
  if (length(i) == 0) return(default)
  if (i == length(args)) stop(flag, " needs a value")
  args[i + 1]
}
CHECK_NAMES <- "--check-names" %in% args

this_file <- sub("^--file=", "", grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE))
if (length(this_file) == 0) this_file <- "tools/parity_ledger.R"
ROOT <- normalizePath(file.path(dirname(this_file), ".."), mustWork = TRUE)

R_LEDGER_PATH <- file.path(ROOT, "docs", "design", "capability-status.md")

JULIA_REPO_DEFAULT <- "/Users/z3437171/Dropbox/Github Local/GLLVM.jl"
SCRATCHPAD_FALLBACK <- "/private/tmp/claude-503/-Users-z3437171-Dropbox-Github-Local-gllvmTMB/46df980d-b0f8-4444-a181-ed4b4a683bbe/scratchpad/gllvmjl-capability-status-main.md"

julia_path_arg <- get_flag("--julia")
julia_repo <- get_flag("--julia-repo", JULIA_REPO_DEFAULT)
ref <- get_flag("--ref", "origin/main")

# ---------------------------------------------------------------------------
# 1. Load the Julia ledger's raw text.
# ---------------------------------------------------------------------------

julia_source_desc <- NULL
julia_text <- NULL

if (!is.null(julia_path_arg)) {
  if (!file.exists(julia_path_arg)) stop("--julia path does not exist: ", julia_path_arg)
  julia_text <- readLines(julia_path_arg, warn = FALSE)
  julia_source_desc <- paste0("file: ", julia_path_arg)
} else {
  out <- suppressWarnings(system2(
    "git", c("-C", shQuote(julia_repo), "show", paste0(ref, ":docs/design/capability-status.md")),
    stdout = TRUE, stderr = TRUE
  ))
  status <- attr(out, "status")
  if (is.null(status)) status <- 0L
  if (status == 0L && length(out) > 0) {
    julia_text <- out
    julia_source_desc <- paste0("git -C \"", julia_repo, "\" show ", ref, ":docs/design/capability-status.md")
  } else {
    if (!file.exists(SCRATCHPAD_FALLBACK)) {
      stop("git show failed against ", julia_repo, " @ ", ref,
           " AND the scratchpad fallback is missing: ", SCRATCHPAD_FALLBACK)
    }
    julia_text <- readLines(SCRATCHPAD_FALLBACK, warn = FALSE)
    julia_source_desc <- paste0("FALLBACK (git show against \"", julia_repo, "\" @ ", ref,
                                 " failed) -> scratchpad copy: ", SCRATCHPAD_FALLBACK)
  }
}

if (!file.exists(R_LEDGER_PATH)) {
  stop("R ledger not found at ", R_LEDGER_PATH,
       " -- run dev/gapclose/build-capability-status.R first")
}
r_text <- readLines(R_LEDGER_PATH, warn = FALSE)

# ---------------------------------------------------------------------------
# 2. Parsers. Both files are pipe-tables under "## " headings. We only parse
#    tables whose header row is literally "| Capability | Status | ..." --
#    this deliberately EXCLUDES GLLVM.jl's two comparator tables ("surface |
#    R mirror | engine | engine-only" and "family / link | log-det curvature
#    | note"), which are prose evidence, not capability rows (per the B2
#    brief: "the prose... sections are context, not rows"). If a status cell
#    inside a real Capability|Status table ever carries a non-canonical word
#    (Julia's own "**observed**" / "Fisher" markers, seen elsewhere in that
#    file's curvature-census table but never inside a Capability|Status
#    table), normalize_status() below treats it as `implemented` with an
#    "(observed)" note, per the B2 brief.
# ---------------------------------------------------------------------------

strip_md <- function(x) {
  x <- gsub("\\*\\*", "", x)
  trimws(x)
}

normalize_status <- function(raw) {
  raw <- strip_md(raw)
  # first token/word run at the start of the cell
  m <- regmatches(raw, regexec("^([A-Za-z][A-Za-z-]*)", raw))[[1]]
  word <- if (length(m) >= 2) tolower(m[2]) else tolower(raw)
  canonical <- c("implemented", "planned", "missing", "rejected")
  if (word %in% canonical) {
    list(word = word, note = if (nchar(raw) > nchar(word)) trimws(sub(paste0("^", word), "", raw, ignore.case = TRUE)) else "")
  } else {
    list(word = "implemented", note = paste0("(non-canonical status cell '", raw, "' normalized to implemented/observed per B2 brief)"))
  }
}

# Parse a markdown file into: for each "## <group>" section, each pipe-table
# whose header row's first two non-empty cells are "Capability" and "Status".
parse_capability_tables <- function(lines) {
  rows <- list()
  cur_group <- NA_character_
  in_target_table <- FALSE
  n <- length(lines)
  i <- 1
  while (i <= n) {
    ln <- lines[i]
    if (grepl("^##+\\s+", ln)) {
      cur_group <- trimws(sub("^##+\\s+", "", ln))
      in_target_table <- FALSE
      i <- i + 1
      next
    }
    if (grepl("^\\|", ln)) {
      cells <- strsplit(ln, "\\|")[[1]]
      cells <- trimws(cells)
      cells <- cells[cells != "" | seq_along(cells) != 1]  # drop leading empty from split
      cells <- cells[nzchar(cells) | seq_along(cells) > 0]
      # re-split properly: markdown row "| a | b | c |" -> strsplit gives c("", " a ", " b ", " c ")
      raw_cells <- strsplit(ln, "\\|")[[1]]
      if (length(raw_cells) >= 2) raw_cells <- raw_cells[-1]
      if (length(raw_cells) >= 1 && trimws(raw_cells[length(raw_cells)]) == "") {
        raw_cells <- raw_cells[-length(raw_cells)]
      }
      raw_cells <- trimws(raw_cells)
      if (length(raw_cells) >= 2 && tolower(raw_cells[1]) == "capability" && tolower(raw_cells[2]) == "status") {
        in_target_table <- TRUE
        i <- i + 1
        next
      }
      if (grepl("^-{2,}\\s*$", raw_cells[1] %||% "")) { i <- i + 1; next }  # separator row "|---|---|"
      if (in_target_table && length(raw_cells) >= 2 && !grepl("^-+$", gsub("[: ]", "", raw_cells[1]))) {
        name <- raw_cells[1]
        st_raw <- raw_cells[2]
        aliases_raw <- if (length(raw_cells) >= 3) raw_cells[3] else ""
        reg_rows_raw <- if (length(raw_cells) >= 4) raw_cells[4] else ""
        note_raw <- if (length(raw_cells) >= 5) raw_cells[5] else ""
        st <- normalize_status(st_raw)
        rows[[length(rows) + 1]] <- list(
          group = cur_group, name = name, status = st$word, status_note = st$note,
          status_raw = st_raw, aliases = aliases_raw, register_rows = reg_rows_raw, note = note_raw
        )
      } else if (!grepl("^-+$", gsub("[: ]", "", raw_cells[1] %||% "-"))) {
        in_target_table <- FALSE
      }
    } else {
      in_target_table <- FALSE
    }
    i <- i + 1
  }
  rows
}

`%||%` <- function(a, b) if (is.null(a) || length(a) == 0) b else a

julia_rows <- parse_capability_tables(julia_text)
r_rows <- parse_capability_tables(r_text)

if (length(julia_rows) == 0) stop("parsed 0 capability rows from the Julia ledger -- check the source/parser")
if (length(r_rows) == 0) stop("parsed 0 capability rows from the R ledger -- run the B1 generator first")

# ---------------------------------------------------------------------------
# 3. Name normalization + join.
# ---------------------------------------------------------------------------

norm_name <- function(x) {
  x <- gsub("`", "", x)
  x <- gsub("\\s+", " ", x)
  trimws(tolower(x))
}
ultra_norm <- function(x) {
  x <- tolower(x)
  gsub("[^a-z0-9]", "", x)
}

split_aliases <- function(x) {
  if (!nzchar(x)) return(character(0))
  trimws(strsplit(x, ";")[[1]])
}

# R key table: normalized name/alias -> index into r_rows
r_keys <- new.env()
for (idx in seq_along(r_rows)) {
  keys <- c(r_rows[[idx]]$name, split_aliases(r_rows[[idx]]$aliases))
  for (k in keys) assign(norm_name(k), idx, envir = r_keys)
}

matched <- list()      # list(julia_idx, r_idx)
julia_only_idx <- integer(0)
for (j in seq_along(julia_rows)) {
  key <- norm_name(julia_rows[[j]]$name)
  if (exists(key, envir = r_keys, inherits = FALSE)) {
    matched[[length(matched) + 1]] <- list(julia_idx = j, r_idx = get(key, envir = r_keys))
  } else {
    julia_only_idx <- c(julia_only_idx, j)
  }
}
r_matched_idx <- unique(vapply(matched, `[[`, integer(1), "r_idx"))
r_only_idx <- setdiff(seq_along(r_rows), r_matched_idx)

# ---------------------------------------------------------------------------
# 4. Divergence notes on MATCHED rows -- the collision list where BOTH sides
#    have a same-named row but the underlying semantics genuinely differ
#    (not a false join -- a true parity caveat).
# ---------------------------------------------------------------------------

NOTED_DIVERGENCES <- list(
  list(pattern = "^student$",
       reason = "Student-t nu: GLLVM.jl's parity Delta is paid only with nu FIXED on both sides; gllvmTMB's default `student()` ESTIMATES nu per trait -- the two `implemented` statuses are not the same claim."),
  list(pattern = "^kernel",
       reason = "kernel PSD-vs-PD: R's kernel_* keyword family documents a PSD requirement on the supplied K; GLLVM.jl's dense-kernel fitter's positive-definiteness contract has not been cross-checked against that requirement -- treat a status match here as unverified equivalence, not confirmed parity."),
  list(pattern = "^aghq estimator$",
       reason = "AGHQ shape: gllvmTMB's `aghq` is a public opt-in knob (`gllvmTMBcontrol(aghq = ...)`); GLLVM.jl's own AGHQ-shaped kernel (src/families/aghq_grid.jl) is internal-only, unreceipted as a public capability, and its own ledger keeps 'AGHQ estimator' at `missing` -- a genuine status disagreement, not merely a naming collision.")
)

divergence_note_for <- function(name) {
  n <- norm_name(name)
  for (d in NOTED_DIVERGENCES) if (grepl(d$pattern, n)) return(d$reason)
  ""
}

# ---------------------------------------------------------------------------
# 5. Disposition table for Julia-only rows: port (genuinely owed to R) /
#    accounted (engine-internal or already-explained, not owed) / divergence
#    (a real semantic gap under a shared-sounding name). Keyed by normalized
#    Julia row name; a few are also matched by substring for names we expect
#    might appear only in prose (never as a parsed row given the
#    Capability|Status table filter) -- those entries are written for
#    completeness per the B2 brief and are inert (never fire) unless a future
#    edit to the Julia ledger turns them into a real table row.
# ---------------------------------------------------------------------------

