  "concurrent / constrained / rrr ordination (num.lv.c / num.rr)" = "constrained/concurrent RRR ordination (num.lv.c / num.RR): no register row found; genuinely owed",
  "quadratic response" = "quadratic (unimodal) response-curve ordination axis: no register row found; genuinely owed",
  # given by the brief as concepts, not confirmed as parseable rows in the
  # Julia ledger read for this build; kept for completeness, inert if unused
  "select_lv" = "select_lv-style latent-dimension selection helper: not confirmed as a live Julia ledger row at build time; genuinely owed if/when it appears",
  "boundary lrt/anova" = "boundary-aware LRT/anova comparison: not confirmed as a live Julia ledger row at build time; genuinely owed if/when it appears",
  "ordination_uncertainty" = "ordination_uncertainty helper: not confirmed as a live Julia ledger row at build time; genuinely owed if/when it appears"
