  "felsenstein contrasts" = "engine-internal phylo likelihood representation (one of three equivalent forms: sparse CHOLMOD / contrasts / edge-incidence); prose evidence in GLLVM.jl's ledger, not a capability row",
  "edge-incidence" = "engine-internal phylo likelihood representation, same prose note as Felsenstein contrasts above",
