  "relaxed clock" = "UNVERIFIED: phylogenetic relaxed-clock engine internals, not located as an exact row in this build's read of the Julia ledger; included per the B2 brief, treated as engine-internal if it appears",
  "node-frame gradient" = "UNVERIFIED: sparse phylo gradient engine internals, not located as an exact row in this build's read of the Julia ledger; included per the B2 brief",
  "takahashi" = "UNVERIFIED: Takahashi selected-inverse sparse linear algebra (cf. the identical DRM.jl precedent entry); not located as an exact row in this build's read of the Julia ledger",
  "em family" = "UNVERIFIED: EM-style estimator engine internals, not located as an exact row in this build's read of the Julia ledger",
  "ppca init" = "UNVERIFIED: probabilistic-PCA starting-value engine internals, not located as an exact row in this build's read of the Julia ledger",
  # Grounded: the Julia file's own "## Laplace curvature" section is a
