  # here for documentation completeness per the B2 brief.
  "laplace curvature contract" = "the family/link log-det curvature census uses a different table header (`family / link | log-det curvature | note`), not `Capability | Status`; excluded from row-level parsing by design (see this script's parser comment), tracked as an engine-internal precision detail, not a capability row",

  # --- Discovered running this tool against the live GLLVM.jl repo ---------
  # Julia's own R<->Julia parity-testing infrastructure, not an R capability.
  "light gllvmtmb loglik named routes (63/63)" = "GLLVM.jl's own internal R<->Julia parity-testing scaffold (light RCall Delta checks); not a capability of gllvmTMB to mirror",
  "shared-x light loglik gauss/bin/pois (18/18)" = "same as the named-routes row above: Julia's own parity-testing infrastructure, not an R capability",
  # Granularity: R has the capability but under a different, already-matched
