  "species-specific environmental coefficients" = "structurally the same mechanism as the matched 'Fixed-effect covariates X' row (FG-02: (0+trait):x per-species slopes); not tracked as a separate register row",
  "row effects fixed" = "ordinary fixed-effect design terms, covered by the matched 'Fixed-effect covariates X' / 'grouping level x unit' rows; not tracked as a separate register row",
