  "phylo model a public interval promotion" = "duplicate framing of the same LV-08 fence matched to the 'phylo_latent + lv = ~ x (Phylo Model A)' row above -- both sides withhold this promotion",
  "delta/hurdle latent-scale correlation advertising" = "matches R's MIX-10 (mixed-family delta/hurdle latent-scale correlation, `partial`, route-only): both sides fence this advertising claim",
  "non-gaussian reml" = "matches R's own MIS-33 fence (Gaussian-only REML; non-Gaussian REML is not built): both sides refuse this by decision",
  "broad aghq (julia)" = "duplicate of the already-matched 'AGHQ estimator' row (see its NOTED_DIVERGENCES note above) -- GLLVM.jl's ledger lists AGHQ twice (main table + Withdrawn table); this tool joins the first occurrence"
)

DIVERGENCE <- list(
  "student-t nu" = "gllvmTMB estimates nu per trait by default; GLLVM.jl's parity Delta is paid only at fixed nu -- see NOTED_DIVERGENCES on the matched `student` row",
  "kernel psd-vs-pd" = "R's kernel_* keywords document a PSD requirement; GLLVM.jl's PD contract for the same dense-kernel fitter is unverified against it -- see NOTED_DIVERGENCES on the matched kernel rows",
  "aghq shape" = "R's aghq is a public opt-in knob; GLLVM.jl's internal AGHQ-shaped kernel is unreceipted as a public capability and stays `missing` on its own ledger -- see NOTED_DIVERGENCES on the matched `AGHQ estimator` row"
)

disposition_for <- function(name) {
  n <- norm_name(name)
  if (!is.null(PORT[[n]])) return(list(type = "port", reason = PORT[[n]]))
  if (!is.null(ACCOUNTED[[n]])) return(list(type = "accounted", reason = ACCOUNTED[[n]]))
  if (!is.null(DIVERGENCE[[n]])) return(list(type = "divergence", reason = DIVERGENCE[[n]]))
  # substring fallback for the prose-only / possibly-renamed concepts
  for (nm in names(PORT)) if (grepl(nm, n, fixed = TRUE) || grepl(n, nm, fixed = TRUE)) return(list(type = "port", reason = PORT[[nm]]))
  for (nm in names(ACCOUNTED)) if (grepl(nm, n, fixed = TRUE)) return(list(type = "accounted", reason = ACCOUNTED[[nm]]))
  for (nm in names(DIVERGENCE)) if (grepl(nm, n, fixed = TRUE)) return(list(type = "divergence", reason = DIVERGENCE[[nm]]))
  NULL
}

# ---------------------------------------------------------------------------
# 6. --check-names: near-miss detection (case/space/punctuation-insensitive
#    match that is NOT an exact norm_name() match -- almost always a real
#    formatting bug, since a genuine concept difference should not hinge on
#    case/spacing) + the four required grouping-level rows.
# ---------------------------------------------------------------------------

r_ultra <- setNames(vapply(r_rows, function(r) ultra_norm(r$name), character(1)), NULL)
julia_ultra <- setNames(vapply(julia_rows, function(r) ultra_norm(r$name), character(1)), NULL)

near_misses <- character(0)
for (j in julia_only_idx) {
  ju <- ultra_norm(julia_rows[[j]]$name)
  hit <- which(r_ultra == ju)
  if (length(hit) > 0) {
    near_misses <- c(near_misses, sprintf("Julia %-60s <-> R %s",
                                           shQuote(julia_rows[[j]]$name), shQuote(r_rows[[hit[1]]]$name)))
  }
}
for (ri in r_only_idx) {
  ru <- ultra_norm(r_rows[[ri]]$name)
  hit <- which(julia_ultra == ru)
  if (length(hit) > 0) {
    near_misses <- c(near_misses, sprintf("R %-60s <-> Julia %s",
                                           shQuote(r_rows[[ri]]$name), shQuote(julia_rows[[hit[1]]]$name)))
  }
}
near_misses <- unique(near_misses)

REQUIRED_GROUPING_ROWS <- c("grouping level × unit", "grouping level × unit_obs",
                             "grouping level × cluster", "grouping level × cluster2")
r_names_norm <- vapply(r_rows, function(r) norm_name(r$name), character(1))
missing_grouping <- REQUIRED_GROUPING_ROWS[!norm_name(REQUIRED_GROUPING_ROWS) %in% r_names_norm]

# ---------------------------------------------------------------------------
# 7. Collision guard: named collision rows must never join to the WRONG
#    Julia row (verified structurally, not just printed).
# ---------------------------------------------------------------------------

collision_failures <- character(0)
cum_logit_r <- r_rows[[which(r_names_norm == norm_name("cumulative_logit (missing-predictor family)"))[1]]]
if (!is.null(cum_logit_r)) {
  key <- norm_name(cum_logit_r$name)
  if (exists(key, envir = r_keys, inherits = FALSE)) {
    idx <- get(key, envir = r_keys)
    if (!identical(idx, which(r_names_norm == key)[1])) collision_failures <- c(collision_failures, "cumulative_logit key routes to the wrong R row index")
  }
  matched_julia <- Filter(function(m) m$r_idx == which(r_names_norm == key)[1], matched)
  if (length(matched_julia) > 0) {
    for (mm in matched_julia) {
      jname <- norm_name(julia_rows[[mm$julia_idx]]$name)
      if (grepl("ordinal", jname)) {
        collision_failures <- c(collision_failures,
          sprintf("cumulative_logit (missing-predictor family) incorrectly joined to Julia row '%s'", julia_rows[[mm$julia_idx]]$name))
      }
    }
  }
}

# ---------------------------------------------------------------------------
# 8. Report.
# ---------------------------------------------------------------------------

cat(sprintf("R ledger:     %s (%d rows)\n", R_LEDGER_PATH, length(r_rows)))
cat(sprintf("Julia ledger: %s (%d rows)\n", julia_source_desc, length(julia_rows)))
cat("\n")

cat(sprintf("COUNTS: %d matched, %d R-only, %d Julia-only\n",
            length(matched), length(r_only_idx), length(julia_only_idx)))
cat("\n")

cat(sprintf("MATCHED ROWS (%d)\n", length(matched)))
for (m in matched) {
  jr <- julia_rows[[m$julia_idx]]; rr <- r_rows[[m$r_idx]]
  agree <- identical(
    sub(" .*$", "", jr$status),
    sub(" .*$", "", rr$status)
  )
  # `implemented` on both sides still agrees; anything else needing nuance
  # (e.g. R `scope-limited` vs Julia `implemented`) is flagged.
  flag <- if (jr$status == rr$status) "AGREE" else if (jr$status == "implemented" && rr$status %in% c("scope-limited", "point-fit-recovery")) "R-NARROWER" else if (rr$status == "implemented" && jr$status != "implemented") "R-AHEAD" else "DIFFER"
  dv <- divergence_note_for(rr$name)
  cat(sprintf("  [%-11s] %-70s R=%-20s Julia=%s%s\n",
              flag, rr$name, rr$status, jr$status,
              if (nzchar(dv)) paste0("\n      divergence: ", dv) else ""))
}
cat("\n")

cat(sprintf("AHEAD OF gllvmTMB, ACCOUNTED FOR IN WRITING -- Julia-only rows with a disposition (%d)\n", length(julia_only_idx)))
undispositioned <- character(0)
for (j in julia_only_idx) {
  jr <- julia_rows[[j]]
  d <- disposition_for(jr$name)
  if (is.null(d)) {
    undispositioned <- c(undispositioned, jr$name)
    cat(sprintf("  [UNDISPOSITIONED] %s (status=%s)\n", jr$name, jr$status))
  } else {
    cat(sprintf("  [%-10s] %-60s %s\n", toupper(d$type), jr$name, d$reason))
  }
}
cat("\n")

cat(sprintf("AHEAD OF GLLVM.jl -- R-only rows (%d), for symmetry\n", length(r_only_idx)))
for (ri in r_only_idx) {
  rr <- r_rows[[ri]]
  cat(sprintf("  %-70s R status=%s\n", rr$name, rr$status))
}
cat("\n")

if (CHECK_NAMES) {
  cat("--check-names\n")
  if (length(near_misses) == 0) {
    cat("0 near-miss\n")
  } else {
    cat(sprintf("%d near-miss(es) -- likely formatting bugs, not real divergences:\n", length(near_misses)))
    for (nm in near_misses) cat("  ", nm, "\n")
  }
  if (length(missing_grouping) == 0) {
    cat("all 4 grouping-level rows present (unit / unit_obs / cluster / cluster2)\n")
  } else {
    cat("MISSING grouping-level rows: ", paste(missing_grouping, collapse = ", "), "\n")
  }
  cat("\n")
}

closure_ok <- length(undispositioned) == 0 && length(near_misses) == 0 &&
  length(missing_grouping) == 0 && length(collision_failures) == 0

if (closure_ok) {
  cat(sprintf("CLOSURE: PASS -- every one of %d Julia-only rows carries a port/accounted/divergence disposition, 0 near-misses, all 4 grouping-level rows present, collision rows join correctly\n",
              length(julia_only_idx)))
} else {
  cat("CLOSURE: FAIL\n")
  if (length(undispositioned) > 0) cat(sprintf("  %d Julia-only row(s) have no disposition: %s\n", length(undispositioned), paste(undispositioned, collapse = "; ")))
  if (length(near_misses) > 0) cat(sprintf("  %d near-miss name(s)\n", length(near_misses)))
  if (length(missing_grouping) > 0) cat(sprintf("  missing grouping-level rows: %s\n", paste(missing_grouping, collapse = ", ")))
  if (length(collision_failures) > 0) cat(sprintf("  collision failures: %s\n", paste(collision_failures, collapse = "; ")))
}

quit(status = if (closure_ok) 0L else 1L, save = "no")
